import{_ as e,o as t,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Annaprasana source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/18-annaprasana-profile.md","filePath":"reference/18-annaprasana-profile.md","lastUpdated":1788517140000}'),o={name:"reference/18-annaprasana-profile.md"};function s(i,a,d,c,h,l){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="annaprasana-source-profile" tabindex="-1">Annaprasana source profile <a class="header-anchor" href="#annaprasana-source-profile" aria-label="Permalink to &quot;Annaprasana source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The configured first-feeding profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “First feeding on rice (Annaprasana),” printed pages 21–22 (PDF pages 25–26). Its “usual unfavorable Tithis” reference is resolved through the same book&#39;s general Panchanga Suddhi list in Chapter V, printed page 11 (PDF page 15):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. The election supplements rather than replaces pediatric feeding guidance and the family&#39;s ritual tradition.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Perform in the 6th, 8th, 9th or 12th month; month is most important</td><td><code>manual_checks</code></td><td>Child age is not an input, so every result discloses this prerequisite.</td></tr><tr><td>Twelve named Nakshatras are admitted; seven others explicitly rejected</td><td><code>allowed_nakshatras</code></td><td>Conservative allow-list; unlisted active slot-time Nakshatras reject the candidate.</td></tr><tr><td>Avoid usual unfavorable Tithis</td><td><code>avoid_tithi_numbers</code></td><td>Cross-referenced to Chapter V&#39;s 4th, 6th, 8th, 12th, 14th, Purnima and Amavasya list; terminal days both map to 15.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday are good</td><td><code>allowed_varas</code></td><td>Other weekdays reject the day with an explicit reason.</td></tr><tr><td>Mesha, Vrischika and Meena rising are inauspicious</td><td><code>allowed_lagnas</code></td><td>The other nine Rasis form the conservative slot-time allow-list.</td></tr><tr><td>Leave the 10th vacant; keep Budha/Mangala/Shukra out of the 7th/8th/9th respectively</td><td><code>ELECTION_CHART_RULES[annaprasana]</code></td><td>The Drik browser rejects a failure at any sampled state (edges and both sides of known interior Lagna transitions). Vacancy counts all nine projected grahas.</td></tr><tr><td>Budha, Guru or Shukra in Lagna; no malefic in Lagna</td><td><code>manual_checks</code></td><td>Benefic/malefic classification and the remaining fortification judgment stay manual.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>The existing samskara filters, hard avoid windows, Shubh-Choghadiya and Tithi-family ranking preferences, personal scoring and relative tiers are shared project rules and are not established by this locator. MCP exposes the stable <code>muhurta.annaprasana</code> claim and all manual checks; the browser consumes the same generated activity contract and adds a Drik-only chart post-screen. The chart service does not run in Python/MCP. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p>',9)])])}const m=e(o,[["render",s]]);export{u as __pageData,m as default};
